    "raw": "טבית עיראקי מסורתי\nכמות מקורית: 8 מנות · הכנה: 30 דקות · בישול: 8.5 שעות\n\nמצרכים\nעוף שלם קטן מחולק (או 3 כרעיים מחולקות)\n1.2 ק\"ג בשר שפונדרה חתוך לקוביות גדולות\n2.5 כוסות אורז פרסי מושרה חצי שעה ומסונן\n2 עגבניות קטנות קצוצות דק ו-2 בצלים בינוניים קצוצים\n1.5 כפות גדושות רסק עגבניות ו-2 כפות סילאן\n3.75–4.5 כוסות מים רותחים\n1.5 כפות בהרט, 3/4 כפית קינמון, 3/4 כפית ג'ינג'ר טחון, 2 כפיות פפריקה, 1 כף מלח ופלפל שחור\n\nאופן ההכנה\nצריבה והרכבה: צורבים את קוביות השפונדרה בסיר כבד ומוציאים. מטגנים בצל אחד ואת חלקי העוף להזהבה, מחזירים את הבשר ומוסיפים מעל את האורז המעורבב עם העגבניות והבצל השני.\nבישול: יוצקים מעל את המים הרותחים המעורבבים עם רסק העגבניות, הסילאן והתבלינים, מרתיחים ומבשלים על אש קטנה 30 דקות. מעבירים לתנור ב-110 מעלות למשך 8 שעות.",
