      "צריבה וריכוך: צורבים את קוביות האונטריב בסיר כבד ומוציאים. מקרמלים את הבצלים 15 דקות, מוסיפים ג'ינג'ר, שום, סלרי וגזר. מחזירים את הבשר והתבלינים, מכסים במים רותחים ומבשלים שעתיים על אש קטנה.",
      "הרכבה ואפייה: קולים את הפריקי המסוננת 2–3 דקות במחבת עם כף שמן, מוסיפים לסיר הבשר עם הפירות היבשים, הסילאן והמלח (הנוזלים צריכים לכסות ב-1 ס\"מ), ואופים מכוסה ב-160 מעלות למשך 45–60 דקות."
