    "raw": "עוגת גבינה אפויה קלאסית\nעוגת גבינה גבוהה ואוורירית על בסיס פתי בר חמאתי באפייה דו-שלבית עם אמבט מים.\n\nמצרכים\nלבסיס: 150 גרם ביסקוויטים פתי בר טחונים + 100 גרם חמאה מומסת\n500 גרם גבינת שמנת (26% ומעלה) + 300 גרם גבינה לבנה 9% + 250 גרם שמנת של פעם\n40 גרם (1/3 כוס) קורנפלור + 40 גרם (1/3 כוס) קמח לבן\n4 חלמונים M + 150 גרם סוכר + תוכן מקל וניל וגרידת חצי לימון\n4 חלבונים M + 80 גרם (6 כפות) סוכר להקצפה\n\nאופן ההכנה\nמהדקים פירורי ביסקוויטים וחמאה מומסת לתחתית תבנית מרופדת ושומרים במקפיא.\nמערבבים את הגבינות, הקמח, הקורנפלור, הווניל, גרידת הלימון, 150 גרם סוכר והחלמונים לתערובת חלקה. מקציפים חלבונים עם 80 גרם סוכר לקצף יציב ומקפלים בעדינות לתערובת הגבינות.\nיוצקים לתבנית שדפנותיה שומנו בחמאה רכה. אופים עם תבנית מים רותחים בתחתית התנור ב-250 מעלות ל-10 דקות, מנמיכים ל-150 מעלות ואופים עוד 55 דקות. מצננים שעה בחוץ ו-4 שעות במקרר.",
