    "raw": "רביולי סלק, בורגול ואגוזי מלך\nמנה ראשונה אלגנטית של פרוסות קרפצ'יו סלק דקיקות במילוי בורגול מתובל, אגוזים בדבש ובלסמי.\n\nמצרכים\n2 סלקים פרוסים דק מאוד (כמו קרפצ'יו) מושרים במעט אבקת סוכר, מלח ופלפל\n1 כוס בורגול מושרה ב-1 כוס מים חמים ל-10 דקות\nמיץ לימון, מלח, פלפל שחור ומעט שמן כמהין\nחופן אגוזי מלך קצוצים מעורבבים עם דבש\nעירית או בצל ירוק קצוץ, שמנת חמוצה ובלסמי מצומצם\n\nאופן ההכנה\nמתבלים את הבורגול המושרה בלימון, מלח, פלפל ומעט שמן כמהין.\nמניחים על כל פרוסת סלק אגוזי מלך בדבש, כפית בורגול, עירית, מעט שמנת ובלסמי מצומצם, וסוגרים בפרוסת סלק נוספת.",
