    "tips": [],
    "notes": "",
    "raw": "עוגת גבינה ולוטוס קרה\nעוגת גבינה וקצפת ללא אפייה על בסיס עוגיות לוטוס חמאתי בציפוי קרם לוטוס מבריק.\n\nמצרכים\n250 גרם עוגיות לוטוס מפוררות + 100 גרם חמאה מומסת\n500 מ\"ל (2 מכלים) שמנת מתוקה 38%\n8 כפות אינסטנט פודינג וניל + 2 כפות סוכר\n200 גרם גבינת שמנת או גבינת סקי 9%\n150 גרם ממרח לוטוס חלק לציפוי\n\nאופן ההכנה\nמערבבים פירורי לוטוס וחמאה מומסת, מהדקים לתחתית תבנית מרופדת בשקף/נייר אפייה.\nמקציפים שמנת מתוקה, סוכר ואינסטנט פודינג לקצפת יציבה, מקפלים פנימה את הגבינה, משטחים על הבסיס ומקררים לילה (ולאחר מכן חצי שעה במקפיא).\nממיסים ממרח לוטוס במיקרוגל למרקם נוזלי, יוצקים בשכבה אחידה מעל העוגה הקרה ומקררים שעה נוספת.",
    "sourceUrl": "https://drive.google.com/file/d/1jgWWdLS9F015dwWebPTOVMFk-QN_TFGu/view",
