    "tips": [],
    "notes": "",
    "raw": "רביולי בחמאה שרופה, ערמונים ובטטה\nרביולי ברוטב חמאה חומה אגוזית, שמנת, קוביות בטטה צלויות, ערמונים, תרד ושמן כמהין.\n\nמצרכים\n500 גרם רביולי גבינות או בטטה\n1 בטטה בינונית חתוכה לקוביות קטנות + טימין, שמן זית ומלח\n50 גרם חמאה + 250 מ\"ל שמנת לבישול או שמנת מתוקה\n100 גרם ערמונים קלויים קצוצים + 2 כפות שקדים טחונים\nחופן עלי תרד טריים, 1 כפית סילאן, אגוז מוסקט, מלח, פלפל ומעט שמן כמהין\n\nאופן ההכנה\nצולים את קוביות הבטטה עם שמן זית, טימין ומלח בתנור עד להזהבה.\nממיסים חמאה במחבת רחבה עד שהיא משחימה ומפיצה ניחוח אגוזי, מוסיפים שמנת, שקדים טחונים, ערמונים, סילאן, מוסקט, מלח, פלפל ומעט שמן כמהין.\nמוסיפים את עלי התרד, הבטטה הצלויה והרביולי המבושלים, מקפיצים דקה לאיחוד ומגישים.",
