    "id": "chat-dry-brine-steak",
    "title": "סטייק אנטריקוט בשיטת Dry-Brine",
    "category": "בשר",
    "description": "המלחה יבשה מראש על רשת במקרר ל-24 שעות לקבלת קראסט מושלם וצריבה בחמאה, שום ורוזמרין.",
