    "tips": [],
    "notes": "",
    "raw": "סטייק אנטריקוט בשיטת Dry-Brine\nהמלחה יבשה מראש על רשת במקרר ל-24 שעות לקבלת קראסט מושלם וצריבה בחמאה, שום ורוזמרין.\n\nמצרכים\n2 סטייקים אנטריקוט או ריב-איי בעובי 4 ס\"מ (כ-400 גרם כ\"א)\n1.5% ממשקל הבשר מלח ים אטלנטי גס\n2 כפות שמן זרעי ענבים (לצריבה בטמפרטורה גבוהה)\n40 גרם חמאה, 3 שיני שום מעוכות, 2 ענפי רוזמרין ופלפל שחור גרוס\n\nאופן ההכנה\nממליחים את הסטייקים מכל הצדדים ומניחים על רשת פתוחה במקרר ל-24–48 שעות לייבוש שטח הפנים.\nצורבים במחבת ברזל יצוק לוהטת עם מעט שמן ענבים כ-2 דקות מכל צד, מוסיפים חמאה, שום ורוזמרין ומשקים (Basting) את הסטייק עד ל-54 מעלות פנימי. נותנים מנוחה של 8 דקות לפני הפריסה.",
    "sourceUrl": "",
    "sourceName": "שיחות Gemini",
