      "מחממים תנור ל־110°C. מחממים מחבת כבדה, משתמשים בשמן לציפוי דק וצורבים את כל פני הבשר: כ־60–90 שניות בכל צד רחב וכ־30–45 שניות בקצוות.",
      "לאחר הצריבה מורחים חרדל דיז׳ון ומתבלים בפלפל שחור, אבקת שום ואבקת בצל. מעבירים לרשת מעל תבנית, ללא כיסוי.",
      "נועצים מדחום במרכז החלק העבה של כל חתיכה, בלי להסתמך על זמן קבוע. בגרסה המוקדמת יעד ההוצאה היה 54°C; בעקבות מדידה בפועל שהראתה כמעט אפס עלייה במנוחה, התיקון האחרון היה להוציא ב־56°C. מוציאים כל חתיכה בנפרד כשהיא מגיעה ליעד.",
